private WAFFE reservewaffe;","language":"java","showLineNumbers":false},"id":"7ba856e1-6ba3-43ce-9ea8-87b7b5c4f10d"}],"id":"b998bd59-88e2-437a-b046-874987f2878e"},"id":"189071-course-page","title":"Referenzattribute"},{"content":{"plugin":"rows","state":[{"plugin":"text","state":[{"type":"p","children":[{"text":"Nun hast du gesehen, wie man Referenzattribute deklarieren kann, also dem Computer sagen kann, dass ein Objekt von einer anderen Klasse mit einem Objekt der eigenen Klasse verlinkt werden kann."}]}],"id":"ea5297b3-ba96-4b28-b1a2-64f639c481bd"},{"plugin":"text","state":[{"type":"p","children":[{"text":"Wie du ein Referenzattribut initialisierst und damit kommunizierst, wird Inhalt eines weiteren Kurses sein."}]}],"id":"61ed44d8-4e2b-459d-9e2d-77a1da0c9fef"}],"id":"ad4547bd-158a-4b7b-87ed-2fcc1b7809a9"},"id":"189072-course-page","title":"Zusammenfassung"}]},"id":"9b4d6f2f-c7ce-4c9c-aae4-0340438f0e43"}}
